    if lhs.torrentInfoHashV1 != rhs.torrentInfoHashV1 {return false}
    if lhs.torrentInfoHashV2 != rhs.torrentInfoHashV2 {return false}
    if lhs.entries != rhs.entries {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
